#!/usr/bin/env python3
# luxarch:background-shells hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Name the background shells a session has left running, because they read as work still going on.

Stop hook: when this session has a Bash tool shell over an hour old, block the end of the turn once and
name each one, so the agent stops what is done or says what it is waiting for. A job started this turn
and awaited is under the hour and says nothing. It blocks once per turn (`stop_hook_active`), and it
passes if `ps` cannot be read: a reminder must never trap a session. It covers subagents' shells, which
run in the session's own process.

By hand, read-only:
  python3 .claude/hooks/background-shells.py --own   this session's shells, whatever their age
  python3 .claude/hooks/background-shells.py --all   every session on this machine, each one's old
                                                     shells, shells whose session is gone, containers
                                                     up over a day, and what docker could reclaim

A Bash tool shell is known by the shell snapshot its command sources. A process a shell left behind
with its parent gone, or anything else not started by the Bash tool, is not read as one.
"""

from __future__ import annotations

import json
import os
import re
import subprocess
import sys

_MARKER = "shell-snapshots/snapshot-"
_OLD_SECONDS = 3600
_DAY = 86400
_RUN_ERRORS: tuple[type[Exception], ...] = (OSError, subprocess.SubprocessError)


def _run(*argv: str) -> str:
    try:
        return subprocess.run(
            argv,
            capture_output=True,
            text=True,
            errors="replace",
            timeout=20,
            check=False,
            env={**os.environ, "LC_ALL": "C"},
        ).stdout
    except _RUN_ERRORS:
        return ""


def _table() -> dict[int, tuple[int, int, str]]:
    """pid -> (parent pid, age in seconds, command line)."""
    rows: dict[int, tuple[int, int, str]] = {}
    for line in _run("ps", "-A", "-o", "pid=,ppid=,etime=,command=").splitlines():
        words = line.split(None, 3)
        if len(words) < 4 or not (words[0].isdigit() and words[1].isdigit()):
            continue
        try:
            rows[int(words[0])] = (int(words[1]), _elapsed(words[2]), words[3])
        except ValueError:
            continue
    return rows


def _elapsed(etime: str) -> int:
    days, _, clock = etime.rpartition("-")
    seconds = 0
    for part in clock.split(":"):
        seconds = seconds * 60 + int(part)
    return seconds + (int(days) * _DAY if days else 0)


def _ancestors(table: dict[int, tuple[int, int, str]]) -> set[int]:
    """This process and everything above it, short of init."""
    out: set[int] = set()
    pid = os.getpid()
    while pid > 1 and pid not in out:
        out.add(pid)
        pid = table[pid][0] if pid in table else 0
    return out


def _own_shells(table: dict[int, tuple[int, int, str]]) -> list[int]:
    """Bash tool shells beside this process: under a process above it, and not above it themselves."""
    above = _ancestors(table)
    return sorted(
        pid
        for pid, (parent, _age, cmd) in table.items()
        if _MARKER in cmd and parent in above and pid not in above
    )


def _what(cmd: str) -> str:
    """The command the agent wrote, out of the shell's own preamble."""
    m = re.search(r"eval '(.*?)' *< */dev/null", cmd, re.S)
    return " ".join((m.group(1) if m else cmd).split())[:110]


def _age(seconds: int) -> str:
    if seconds >= _DAY:
        return f"{seconds // _DAY}d{seconds % _DAY // 3600}h"
    return f"{seconds // 3600}h{seconds % 3600 // 60:02d}m"


def _line(pid: int, table: dict[int, tuple[int, int, str]]) -> str:
    return f"  pid {pid}  {_age(table[pid][1])}  {_what(table[pid][2])}"


def _hook() -> int:
    try:
        event = json.load(sys.stdin)
    except ValueError:
        event = {}
    if isinstance(event, dict) and event.get("stop_hook_active"):
        return 0
    table = _table()
    old = [p for p in _own_shells(table) if table[p][1] >= _OLD_SECONDS]
    if not old:
        return 0
    print(
        "This session has background shells over an hour old. They read as work still going on, and "
        "the owner cannot tell them from it:\n"
        + "\n".join(_line(p, table) for p in old)
        + "\nFor each: stop it if its work is done or what it waits for can no longer come (TaskStop, "
        "or kill <pid>), or say in your reply what it is still doing.",
        file=sys.stderr,
    )
    return 2


def _list_own() -> int:
    table = _table()
    own = _own_shells(table)
    print(f"{len(own)} background shell(s) in this session")
    for pid in own:
        print(_line(pid, table))
    return 0


def _is_session(cmd: str) -> bool:
    return os.path.basename(cmd.split(None, 1)[0]) == "claude" if cmd else False


def _survey() -> int:
    table = _table()
    sessions = {p for p, row in table.items() if _is_session(row[2])}
    shells = [p for p, row in table.items() if _MARKER in row[2]]
    print(f"{len(sessions)} Claude session(s) on this machine")
    for s in sorted(sessions, key=lambda p: -table[p][1]):
        own = [p for p in shells if table[p][0] == s]
        old = [p for p in own if table[p][1] >= _OLD_SECONDS]
        print(
            f"session pid {s}, up {_age(table[s][1])}: {len(own)} shell(s), {len(old)} over an hour"
        )
        for p in old:
            print(_line(p, table))
    orphans = [p for p in shells if table[p][0] not in sessions]
    print(f"{len(orphans)} shell(s) whose session is gone")
    for p in orphans:
        print(_line(p, table))
    up = _run("docker", "ps", "--format", "{{.Names}}|{{.Status}}")
    old_up = [ln for ln in up.splitlines() if re.search(r"Up \d+ (day|week|month)", ln)]
    print(f"{len(old_up)} container(s) up over a day, a dev stack's included")
    for ln in old_up:
        print("  " + ln.replace("|", "  "))
    df = _run(
        "docker", "system", "df", "--format", "{{.Type}}: {{.Reclaimable}} reclaimable"
    )
    if df.strip():
        print("docker disk:")
        print("".join(f"  {ln}\n" for ln in df.splitlines()).rstrip())
    print("Read-only: removing anything here is the owner's call.")
    return 0


def main() -> int:
    args = sys.argv[1:]
    if not args:
        try:
            return _hook()
        except (
            Exception
        ):  # a reminder that cannot read must never hold a session at its Stop
            return 0
    if args == ["--all"]:
        return _survey()
    if args == ["--own"]:
        return _list_own()
    print("usage: background-shells.py [--own | --all]", file=sys.stderr)
    return 2


sys.exit(main())
